Dưới đây là đoạn code JavaScript cài đặt thuật toán sắp xếp nổi bọt (Bubble Sort):

```javascript
function bubbleSort(arr) {
  let len = arr.length;
  let swapped;

  do {
    swapped = false;
    for (let i = 0; i < len - 1; i++) {
      if (arr[i] > arr[i + 1]) {
        // Đổi chỗ các phần tử nếu chúng không đúng thứ tự
        let tmp = arr[i];
        arr[i] = arr[i + 1];
        arr[i + 1] = tmp;
        swapped = true;
      }
    }
    // Giảm phạm vi vòng lặp vì phần tử lớn nhất đã trôi về cuối
    len--;
  } while (swapped);

  return arr;
}

// Ví dụ sử dụng:
const numbers = [5, 3, 8, 4, 2];
console.log("Trước khi sắp xếp:", numbers);
bubbleSort(numbers);
console.log("Sau khi sắp xếp:", numbers);
```
